33	    /** 01 §7.1 — 단일 트랜잭션 + 조건부 원자 UPDATE. */
34	    @Transactional
35	    public OrderResponse create(CreateOrderRequest request) {
36	        List<OrderItemRequest> items = request.items();
37	
38	        // [2] 존재 확인(404) — 어떤 차감보다 먼저 전부 끝낸다.
39	        List<Long> ids = items.stream().map(OrderItemRequest::productId).toList();
40	        Map<Long, Product> products = new HashMap<>();
41	        for (Product p : productRepository.findAllById(ids)) {
42	            products.put(p.getId(), p);
43	        }
44	        List<Long> missing = ids.stream()
45	                .filter(id -> !products.containsKey(id))
46	                .sorted()
47	                .toList();
48	        if (!missing.isEmpty()) {
49	            throw new ProductNotFoundException(missing);
50	        }
51	
52	        // 금액 계산(400 overflow) — 404 다음, 재고 차감(409) 전.
53	        long total = 0;
54	        try {
55	            for (OrderItemRequest item : items) {
56	                long unitPrice = products.get(item.productId()).getPrice();
57	                total = Math.addExact(total, Math.multiplyExact(unitPrice, (long) item.quantity()));
58	            }
59	        } catch (ArithmeticException e) {
60	            throw new AmountOverflowException();
61	        }
62	
63	        // [3] 재고 차감(409) — productId 오름차순으로 데드락 회피. 실패 시 예외로 전체 롤백.
64	        items.stream()
65	                .sorted(Comparator.comparing(OrderItemRequest::productId))
66	                .forEach(item -> {
67	                    int updated = productRepository.decreaseStock(item.productId(), item.quantity());
68	                    if (updated == 0) {
69	                        throw new InsufficientStockException(item.productId(), item.quantity());
70	                    }
71	                });
72	
73	        // 주문 저장 — 요청 순서대로 항목을 추가한다.
74	        Order order = new Order(total);
75	        for (OrderItemRequest item : items) {
76	            long unitPrice = products.get(item.productId()).getPrice();
77	            order.addItem(new OrderItem(order, item.productId(), item.quantity(), unitPrice));
78	        }
79	        orderRepository.save(order);
80	        return OrderResponse.from(order);
81	    }
82	
83	    @Transactional(readOnly = true)
84	    public OrderResponse getById(Long id) {
85	        return orderRepository.findById(id)
86	                .map(OrderResponse::from)
87	                .orElseThrow(() -> new OrderNotFoundException(id));
88	    }
89	
90	    /** 01 §7.2 — 주문 행 비관적 락 + 원자 증가 UPDATE. */
91	    @Transactional
92	    public OrderResponse cancel(Long id) {
93	        Order order = orderRepository.findByIdForUpdate(id)
94	                .orElseThrow(() -> new OrderNotFoundException(id));
95	        order.cancel();
96	        order.getItems().stream()
97	                .sorted(Comparator.comparing(OrderItem::getProductId))
98	                .forEach(item -> productRepository.increaseStock(item.getProductId(), item.getQuantity()));
99	        return OrderResponse.from(order);
100	    }
101	
102	    @Transactional(readOnly = true)
103	    public PageResponse<OrderResponse> list(int page, int size) {
104	        PageRequest pageable = PageRequest.of(page, size,
105	                Sort.by(Sort.Order.desc("createdAt"), Sort.Order.desc("id")));
106	        Page<OrderResponse> result = orderRepository.findAll(pageable).map(OrderResponse::from);
107	        return PageResponse.of(result, page, size);
108	    }
109	}
