39	/**
40	 * 모든 에러를 RFC 9457 ProblemDetail로 변환하고 Content-Type을 application/problem+json으로 고정한다.
41	 * (클라이언트 Accept와 무관)
42	 */
43	@RestControllerAdvice
44	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
45	
46	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
47	
48	    // ---- Content-Type 고정: 상속한 Spring 기본 처리(404 경로, 405, 415 등)도 이 지점을 지난다.
49	    @Override
50	    protected ResponseEntity<Object> createResponseEntity(Object body, HttpHeaders headers,
51	            HttpStatusCode statusCode, WebRequest request) {
52	        HttpHeaders copy = new HttpHeaders();
53	        copy.putAll(headers);
54	        copy.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
55	        return new ResponseEntity<>(body, copy, statusCode);
56	    }
57	
58	    private ResponseEntity<Object> problem(HttpStatus status, URI type, String title, String detail,
59	            WebRequest request, Map<String, Object> extensions) {
60	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
61	        pd.setType(type);
62	        pd.setTitle(title);
63	        if (request instanceof ServletWebRequest swr) {
64	            pd.setInstance(URI.create(swr.getRequest().getRequestURI()));
65	        }
66	        extensions.forEach(pd::setProperty);
67	        return ResponseEntity.status(status)
68	                .contentType(MediaType.APPLICATION_PROBLEM_JSON)
69	                .body(pd);
70	    }
71	
72	    private ResponseEntity<Object> problem(HttpStatus status, URI type, String title, String detail,
73	            WebRequest request) {
74	        return problem(status, type, title, detail, request, Map.of());
75	    }
76	
77	    // ---- 400 : 검증 / 파싱 / 타입 변환
78	
79	    @Override
80	    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,
81	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
82	        List<Map<String, String>> errors = new ArrayList<>();
83	        for (ObjectError error : ex.getBindingResult().getAllErrors()) {
84	            String field = error instanceof FieldError fe ? fe.getField() : error.getObjectName();
85	            errors.add(Map.of("field", field, "message", messageOf(error)));
86	        }
87	        return validationProblem(errors, request);
88	    }
89	
90	    @Override
91	    protected ResponseEntity<Object> handleHandlerMethodValidationException(HandlerMethodValidationException ex,
92	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
93	        List<Map<String, String>> errors = new ArrayList<>();
94	        ex.getParameterValidationResults().forEach(result -> {
95	            String name = result.getMethodParameter().getParameterName();
96	            result.getResolvableErrors().forEach(error -> {
97	                String field = error instanceof FieldError fe ? fe.getField() : name;
98	                errors.add(Map.of("field", field == null ? "" : field, "message", messageOf(error)));
99	            });
100	        });
101	        return validationProblem(errors, request);
102	    }
103	
104	    /** @Validated가 붙은 경우에 대한 방어적 처리. */
105	    @ExceptionHandler(ConstraintViolationException.class)
106	    protected ResponseEntity<Object> handleConstraintViolation(ConstraintViolationException ex,
107	            WebRequest request) {
108	        List<Map<String, String>> errors = new ArrayList<>();
109	        for (ConstraintViolation<?> v : ex.getConstraintViolations()) {
110	            errors.add(Map.of("field", v.getPropertyPath().toString(), "message", v.getMessage()));
111	        }
112	        return validationProblem(errors, request);
113	    }
114	
115	    private ResponseEntity<Object> validationProblem(List<Map<String, String>> errors, WebRequest request) {
116	        return problem(HttpStatus.BAD_REQUEST, ProblemTypes.VALIDATION_ERROR, "Validation Failed",
117	                "요청 검증에 실패했습니다.", request, Map.of("errors", errors));
118	    }
119	
120	    private static String messageOf(MessageSourceResolvable error) {
121	        String message = error.getDefaultMessage();
122	        return message == null ? "유효하지 않은 값입니다" : message;
123	    }
124	
125	    @Override
126	    protected ResponseEntity<Object> handleHttpMessageNotReadable(HttpMessageNotReadableException ex,
127	            HttpHeaders headers, HttpStatusCode status, WebRequest request) {
128	        // Jackson 내부 메시지는 노출하지 않는다.
129	        return problem(HttpStatus.BAD_REQUEST, ProblemTypes.MALFORMED_REQUEST, "Malformed Request Body",
130	                "요청 본문을 해석할 수 없습니다.", request);
131	    }
132	
133	    @Override
134	    protected ResponseEntity<Object> handleTypeMismatch(TypeMismatchException ex, HttpHeaders headers,
135	            HttpStatusCode status, WebRequest request) {
136	        String parameter = ex instanceof MethodArgumentTypeMismatchException m ? m.getName() : ex.getPropertyName();
137	        Map<String, Object> ext = parameter == null ? Map.of() : Map.of("parameter", parameter);
138	        return problem(HttpStatus.BAD_REQUEST, ProblemTypes.INVALID_PARAMETER, "Invalid Parameter",
139	                "요청 파라미터의 형식이 올바르지 않습니다.", request, ext);
140	    }
141	
142	    @ExceptionHandler(AmountOverflowException.class)
143	    protected ResponseEntity<Object> handleAmountOverflow(AmountOverflowException ex, WebRequest request) {
144	        return problem(HttpStatus.BAD_REQUEST, ProblemTypes.AMOUNT_OVERFLOW, "Amount Overflow",
145	                ex.getMessage(), request);
146	    }
147	
148	    // ---- 404
149	
150	    @ExceptionHandler(ProductNotFoundException.class)
151	    protected ResponseEntity<Object> handleProductNotFound(ProductNotFoundException ex, WebRequest request) {
152	        return problem(HttpStatus.NOT_FOUND, ProblemTypes.PRODUCT_NOT_FOUND, "Product Not Found",
153	                ex.getMessage(), request, Map.of("productIds", ex.getProductIds()));
154	    }
155	
156	    @ExceptionHandler(OrderNotFoundException.class)
157	    protected ResponseEntity<Object> handleOrderNotFound(OrderNotFoundException ex, WebRequest request) {
158	        return problem(HttpStatus.NOT_FOUND, ProblemTypes.ORDER_NOT_FOUND, "Order Not Found",
159	                ex.getMessage(), request);
160	    }
161	
162	    // ---- 409
163	
164	    @ExceptionHandler(InsufficientStockException.class)
165	    protected ResponseEntity<Object> handleInsufficientStock(InsufficientStockException ex, WebRequest request) {
166	        return problem(HttpStatus.CONFLICT, ProblemTypes.INSUFFICIENT_STOCK, "Insufficient Stock",
167	                ex.getMessage(), request, Map.of("productId", ex.getProductId()));
168	    }
169	
170	    @ExceptionHandler(OrderAlreadyCancelledException.class)
171	    protected ResponseEntity<Object> handleAlreadyCancelled(OrderAlreadyCancelledException ex,
172	            WebRequest request) {
173	        return problem(HttpStatus.CONFLICT, ProblemTypes.ORDER_ALREADY_CANCELLED, "Order Already Cancelled",
174	                ex.getMessage(), request);
175	    }
176	
177	    // ---- 500 : 최후의 방어. 내부 정보는 로그에만.
178	
179	    @ExceptionHandler(Exception.class)
180	    protected ResponseEntity<Object> handleUnexpected(Exception ex, WebRequest request) {
181	        log.error("Unhandled exception", ex);
182	        return problem(HttpStatus.INTERNAL_SERVER_ERROR, ProblemTypes.INTERNAL_ERROR, "Internal Server Error",
183	                "예상치 못한 오류가 발생했습니다.", request);
184	    }
185	}
